337: impl TableColumnStatus {
338:     pub fn field(&self) -> Field {
339:         let mut metadata = std::collections::HashMap::new();
340:         if let Some(expr) = &self.generated_always_as {
341:             let builder = ColumnFeaturesBuilder::new().with_generation_expression(expr.clone());
342:             metadata.extend(builder.build());
343:         }
344:         if let Some(expr) = &self.default {
345:             let builder = ColumnFeaturesBuilder::new().with_current_default(expr.clone());
346:             metadata.extend(builder.build());
347:         }
348:         if let Some(identity) = &self.identity {
349:             let builder = ColumnFeaturesBuilder::new().with_identity(identity);
350:             metadata.extend(builder.build());
351:         }
352:         if let Some(comment) = &self.comment {
353:             metadata.insert("comment".to_string(), comment.clone());
354:         }
355:         let field = Field::new(self.name.clone(), self.data_type.clone(), self.nullable);
356:         if metadata.is_empty() {
357:             field
358:         } else {
359:             field.with_metadata(metadata)
360:         }
361:     }
